window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["mintlify"]={html:"<div class=\"own-mintlify\">\n  <div class=\"ml-promo\">\n    <span>Docs as good as your product &mdash; Northwind is live</span>\n    <a href=\"#pricing\">Read the launch note &rarr;</a>\n  </div>\n\n  <header class=\"ml-nav\">\n    <a class=\"ml-logo\" href=\"#\" aria-label=\"Northwind home\"><span class=\"ml-logo-mark\" aria-hidden=\"true\">N</span>Northwind</a>\n    <nav class=\"ml-nav-links\" aria-label=\"Primary\">\n      <a href=\"#features\">Solutions</a>\n      <a href=\"#pricing\">Pricing</a>\n      <a href=\"#stories\">Customers</a>\n      <a href=\"#docs\">Documentation</a>\n      <a href=\"#\">Changelog</a>\n    </nav>\n    <div class=\"ml-nav-right\">\n      <a class=\"ml-btn ml-btn-secondary\" href=\"#\">Talk to sales</a>\n      <a class=\"ml-btn ml-btn-primary\" href=\"#pricing\">Get started</a>\n      <button class=\"ml-menu\" type=\"button\" aria-label=\"Menu\" data-ml-menu>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <section class=\"ml-hero\" aria-labelledby=\"mlHeroH\">\n    <div class=\"ml-clouds\" aria-hidden=\"true\">\n      <span class=\"ml-cloud ml-cloud-1\"></span>\n      <span class=\"ml-cloud ml-cloud-2\"></span>\n      <span class=\"ml-cloud ml-cloud-3\"></span>\n      <span class=\"ml-cloud ml-cloud-4\"></span>\n    </div>\n    <div class=\"ml-hero-inner\">\n      <h1 id=\"mlHeroH\" class=\"ml-h1\">The intelligent operations platform.</h1>\n      <p class=\"ml-hero-sub\">Turn warehouses, regions and pricing into living documentation every\n        team can read &mdash; modelled from your data, published in seconds.</p>\n      <div class=\"ml-hero-cta\">\n        <a class=\"ml-btn ml-btn-green ml-btn-lg\" href=\"#pricing\">Get started</a>\n        <a class=\"ml-btn ml-btn-secondary ml-btn-lg\" href=\"#docs\">Talk to us</a>\n      </div>\n      <div class=\"ml-mockup\" aria-hidden=\"true\">\n        <div class=\"ml-mock-top\"><span></span><span></span><span></span><i>northwind.app / boards</i></div>\n        <div class=\"ml-mock-body\">\n          <div class=\"ml-mock-side\"><b class=\"is-on\"></b><b></b><b></b><b></b><b></b></div>\n          <div class=\"ml-mock-main\">\n            <div class=\"ml-mock-head\"></div>\n            <div class=\"ml-mock-chart\"><i style=\"--h:40%\"></i><i style=\"--h:68%\"></i><i style=\"--h:52%\"></i><i style=\"--h:84%\"></i><i style=\"--h:64%\"></i><i style=\"--h:92%\"></i><i style=\"--h:74%\"></i></div>\n            <div class=\"ml-mock-lines\"><span></span><span></span><span></span></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"ml-logos\" aria-label=\"Customers\">\n    <div class=\"ml-logos-row\">\n      <span>Anthropic</span><span>Cognition</span><span>Vercel</span><span>Lovable</span><span>Stripe</span><span>Block</span>\n    </div>\n  </section>\n\n  <section id=\"features\" class=\"ml-sec\" aria-labelledby=\"mlFeatH\">\n    <h2 id=\"mlFeatH\" class=\"ml-h2\">Built for the intelligence age.</h2>\n    <p class=\"ml-lead\">Three surfaces, one source of truth. Everything is authored in plain markdown\n      and rendered into the board your team reads.</p>\n    <div class=\"ml-feats\">\n      <article class=\"ml-feat\">\n        <span class=\"ml-fi\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 6h16M4 12h10M4 18h13\"/></svg></span>\n        <h3 class=\"ml-h3\">Living docs</h3>\n        <p class=\"ml-feat-desc\">Boards read from the same source as your docs, so nothing drifts.</p>\n      </article>\n      <article class=\"ml-feat\">\n        <span class=\"ml-fi\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"m8 8-4 4 4 4M16 8l4 4-4 4M13 5l-2 14\"/></svg></span>\n        <h3 class=\"ml-h3\">Code-native</h3>\n        <p class=\"ml-feat-desc\">Author boards in a small API or in markdown; both render the same.</p>\n      </article>\n      <article class=\"ml-feat\">\n        <span class=\"ml-fi\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"M8 12l3 3 5-6\"/></svg></span>\n        <h3 class=\"ml-h3\">Always accurate</h3>\n        <p class=\"ml-feat-desc\">Every number traces back to its query. Reviews are part of the doc.</p>\n      </article>\n    </div>\n\n    <div class=\"ml-split\">\n      <div class=\"ml-split-copy\">\n        <span class=\"ml-eyebrow-chip\">Developer experience</span>\n        <h3 class=\"ml-h2\">Write a board in four lines.</h3>\n        <p class=\"ml-lead\">The Northwind API is small on purpose. Define your metric, list your\n          regions, call publish &mdash; that is the whole happy path.</p>\n        <ul class=\"ml-checks\">\n          <li>Typed SDKs for TypeScript and Python</li>\n          <li>Preview environments on every branch</li>\n          <li>Row-level access out of the box</li>\n        </ul>\n      </div>\n      <div class=\"ml-code\">\n        <div class=\"ml-code-head\"><span>board.ts</span><button type=\"button\" class=\"ml-copy\" data-ml-copy>Copy code</button></div>\n        <pre class=\"ml-code-body\"><span class=\"ml-k\">import</span> { Board } <span class=\"ml-k\">from</span> <span class=\"ml-s\">\"@northwind/sdk\"</span>;\n\n<span class=\"ml-k\">const</span> board = <span class=\"ml-k\">new</span> Board(<span class=\"ml-s\">\"cycle-time\"</span>);\nboard.regions([<span class=\"ml-s\">\"nordics\"</span>, <span class=\"ml-s\">\"apac\"</span>]);\nboard.metric(<span class=\"ml-s\">\"cycle_time\"</span>, { window: <span class=\"ml-s\">\"7d\"</span> });\n<span class=\"ml-k\">await</span> board.publish();</pre>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"stories\" class=\"ml-sec\" aria-labelledby=\"mlStorH\">\n    <h2 id=\"mlStorH\" class=\"ml-h2\">Teams that ship with Northwind.</h2>\n    <div class=\"ml-quote-grid\">\n      <figure class=\"ml-quote-feature\">\n        <blockquote><p>&ldquo;Every batch we consistently see the top-performing operations teams\n          reading their numbers from Northwind.&rdquo;</p></blockquote>\n        <figcaption><b>Priya Raman</b><span>Partner, Northwind Ventures</span></figcaption>\n      </figure>\n      <figure class=\"ml-quote\">\n        <blockquote><p>&ldquo;We replaced four spreadsheets and a weekly email chain with one\n          board. The Monday call is now fifteen minutes.&rdquo;</p></blockquote>\n        <figcaption><b>Cole Andersen</b><span>COO, Harborline</span></figcaption>\n      </figure>\n    </div>\n  </section>\n\n  <section id=\"pricing\" class=\"ml-sec\" aria-labelledby=\"mlPriceH\">\n    <div class=\"ml-price-head\">\n      <h2 id=\"mlPriceH\" class=\"ml-h2\">Pricing on your terms.</h2>\n      <div class=\"ml-toggle\" role=\"group\" aria-label=\"Billing period\">\n        <button type=\"button\" class=\"ml-toggle-btn is-active\" data-ml-bill=\"mo\" aria-pressed=\"true\">Monthly</button>\n        <button type=\"button\" class=\"ml-toggle-btn\" data-ml-bill=\"yr\" aria-pressed=\"false\">Annual <span class=\"ml-badge-discount\">&minus;20%</span></button>\n      </div>\n    </div>\n    <div class=\"ml-price-grid\">\n      <article class=\"ml-price-card\">\n        <h3 class=\"ml-h3\">Free</h3>\n        <p class=\"ml-price\"><b data-ml-price data-mo=\"$0\" data-yr=\"$0\">$0</b><span>/mo</span></p>\n        <ul class=\"ml-price-list\"><li>1 board</li><li>3 regions</li><li>Community support</li></ul>\n        <a class=\"ml-btn ml-btn-secondary ml-btn-block\" href=\"#\">Start free</a>\n      </article>\n      <article class=\"ml-price-card ml-price-featured\">\n        <span class=\"ml-badge-featured\">Featured</span>\n        <h3 class=\"ml-h3\">Lift Off</h3>\n        <p class=\"ml-price\"><b data-ml-price data-mo=\"$49\" data-yr=\"$39\">$49</b><span>/mo</span></p>\n        <ul class=\"ml-price-list\"><li>20 boards</li><li>Unlimited regions</li><li>Scheduled digests</li></ul>\n        <a class=\"ml-btn ml-btn-green ml-btn-block\" href=\"#\">Choose Lift Off</a>\n      </article>\n      <article class=\"ml-price-card\">\n        <h3 class=\"ml-h3\">Custom</h3>\n        <p class=\"ml-price\"><b data-ml-price data-mo=\"Let's talk\" data-yr=\"Let's talk\">Let's talk</b></p>\n        <ul class=\"ml-price-list\"><li>Unlimited boards</li><li>SSO &amp; governance</li><li>Priority support</li></ul>\n        <a class=\"ml-btn ml-btn-secondary ml-btn-block\" href=\"#\">Contact sales</a>\n      </article>\n    </div>\n\n    <div class=\"ml-compare\">\n      <table class=\"ml-table\">\n        <caption class=\"ml-sr\">Feature comparison</caption>\n        <thead><tr><th scope=\"col\">Feature</th><th scope=\"col\">Free</th><th scope=\"col\">Lift Off</th><th scope=\"col\">Custom</th></tr></thead>\n        <tbody>\n          <tr class=\"ml-table-group\"><th scope=\"colgroup\" colspan=\"4\">Boards</th></tr>\n          <tr><td>Boards</td><td>1</td><td>20</td><td>Unlimited</td></tr>\n          <tr><td>Regions per board</td><td>3</td><td>Unlimited</td><td>Unlimited</td></tr>\n          <tr class=\"ml-table-group\"><th scope=\"colgroup\" colspan=\"4\">Governance</th></tr>\n          <tr><td>Single sign-on</td><td>&mdash;</td><td>&mdash;</td><td>&#10003;</td></tr>\n          <tr><td>Row-level access</td><td>&mdash;</td><td>&#10003;</td><td>&#10003;</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <section id=\"docs\" class=\"ml-sec ml-docs\" aria-labelledby=\"mlDocsH\">\n    <div class=\"ml-docs-grid\">\n      <nav class=\"ml-side\" aria-label=\"Documentation\">\n        <p class=\"ml-side-head\">Components</p>\n        <a href=\"#\" class=\"ml-side-link is-active\">Boards</a>\n        <a href=\"#\" class=\"ml-side-link\">Metrics</a>\n        <a href=\"#\" class=\"ml-side-link\">Regions</a>\n        <p class=\"ml-side-head\">Primitives</p>\n        <a href=\"#\" class=\"ml-side-link\">Schedules</a>\n        <a href=\"#\" class=\"ml-side-link\">Exports</a>\n      </nav>\n      <div class=\"ml-docs-body\">\n        <h2 id=\"mlDocsH\" class=\"ml-h3\">Boards</h2>\n        <p class=\"ml-prose\">A board is a published view of one or more metrics across a set of regions.\n          Boards are rendered from the same markdown source as your documentation, so a change in\n          the source is a change on the board.</p>\n        <div class=\"ml-property\">\n          <div class=\"ml-property-head\">\n            <code class=\"ml-code-inline\">defaultIndex</code>\n            <span class=\"ml-badge-type\">number</span>\n            <span class=\"ml-badge-required\">Required</span>\n          </div>\n          <p class=\"ml-property-desc\">The index of the tab selected when the board first renders.</p>\n        </div>\n        <div class=\"ml-property\">\n          <div class=\"ml-property-head\">\n            <code class=\"ml-code-inline\">regions</code>\n            <span class=\"ml-badge-type\">string[]</span>\n          </div>\n          <p class=\"ml-property-desc\">A list of territory keys to include in every metric view.</p>\n        </div>\n      </div>\n      <aside class=\"ml-toc\" aria-label=\"On this page\">\n        <p class=\"ml-side-head\">On this page</p>\n        <a href=\"#docs\" class=\"ml-toc-link is-active\">Overview</a>\n        <a href=\"#docs\" class=\"ml-toc-link\">Properties</a>\n        <a href=\"#docs\" class=\"ml-toc-link\">Examples</a>\n      </aside>\n    </div>\n  </section>\n\n  <footer class=\"ml-foot\">\n    <div class=\"ml-foot-top\">\n      <div class=\"ml-foot-brand\">\n        <span class=\"ml-logo-mark\" aria-hidden=\"true\">N</span>\n        <span>Northwind</span>\n        <p>Operations docs that stay true.</p>\n      </div>\n      <div class=\"ml-foot-grid\">\n        <div class=\"ml-foot-col\"><h3>Explore</h3><a href=\"#\">Solutions</a><a href=\"#\">Pricing</a><a href=\"#\">Customers</a></div>\n        <div class=\"ml-foot-col\"><h3>Resources</h3><a href=\"#\">Docs</a><a href=\"#\">Guides</a><a href=\"#\">Changelog</a></div>\n        <div class=\"ml-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Blog</a></div>\n        <div class=\"ml-foot-col\"><h3>Legal</h3><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Security</a></div>\n      </div>\n    </div>\n    <div class=\"ml-foot-bottom\"><span>&copy; 2026 Northwind Analytics</span><span class=\"ml-foot-links\"><a href=\"#\">Status</a><a href=\"#\">Contact</a></span></div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — own layout in the Mintlify design language ═════════════════\n   Atmospheric sky-to-cream marketing hero with cloud illustration, signature mint\n   green accents, black-pill primary CTAs, Inter for prose with Geist Mono for code,\n   12px cards, and a dense 3-column docs surface (sidebar / prose / TOC). */\n\n.own-mintlify {\n  --primary: #0a0a0a;\n  --charcoal: #1c1c1e;\n  --canvas: #ffffff;\n  --canvas-dark: #0a0a0a;\n  --surface: #f7f7f7;\n  --surface-soft: #fafafa;\n  --surface-code: #1c1c1e;\n  --hairline: #e5e5e5;\n  --hairline-soft: #ededed;\n  --hairline-dark: #1f1f1f;\n  --ink: #0a0a0a;\n  --charcoal-text: #1c1c1e;\n  --slate: #3a3a3c;\n  --steel: #5a5a5c;\n  --stone: #888888;\n  --muted: #a8a8aa;\n  --green: #00d4a4;\n  --green-deep: #00b48a;\n  --green-soft: #7cebcb;\n  --tag: #3772cf;\n  --error: #d45656;\n  --orange: #f55a3c;\n  --sky-from: #87a8c8;\n  --sky-to: #f5e9d8;\n  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;\n  --mono: 'Geist Mono', 'SF Mono', Menlo, Consolas, monospace;\n  --gut: clamp(20px, 5cqi, 48px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n}\n.own-mintlify *,\n.own-mintlify *::before,\n.own-mintlify *::after { box-sizing: border-box; }\n.own-mintlify :focus-visible { outline: 2px solid var(--green-deep); outline-offset: 2px; border-radius: 6px; }\n.own-mintlify .ml-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n\n/* ── type ────────────────────────────────────────────────────────────────── */\n.own-mintlify .ml-h1 { font-weight: 600; font-size: clamp(38px, 6cqi, 72px); line-height: 1.05; letter-spacing: -2px; }\n.own-mintlify .ml-h2 { font-weight: 600; font-size: clamp(28px, 3.6cqi, 48px); line-height: 1.1; letter-spacing: -1px; }\n.own-mintlify .ml-h3 { font-weight: 600; font-size: 22px; line-height: 1.3; }\n.own-mintlify .ml-lead { color: var(--steel); font-size: 18px; line-height: 1.5; max-width: 62ch; margin-top: 14px; }\n.own-mintlify .ml-prose { color: var(--charcoal-text); font-size: 16px; line-height: 1.5; margin: 10px 0 20px; }\n\n/* ── buttons ────────────────────────────────────────────────────────────── */\n.own-mintlify .ml-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 40px; padding: 0 20px; border: 1px solid transparent; border-radius: 9999px; cursor: pointer;\n  font-family: var(--font); font-size: 14px; font-weight: 500; line-height: 1.3;\n  text-decoration: none; transition: filter .15s, background-color .15s, border-color .15s;\n}\n.own-mintlify .ml-btn-lg { height: 46px; padding: 0 26px; font-size: 15px; }\n.own-mintlify .ml-btn-primary { background: var(--primary); color: #fff; }\n.own-mintlify .ml-btn-primary:active { background: var(--charcoal); }\n.own-mintlify .ml-btn-secondary { background: transparent; color: var(--ink); border-color: var(--hairline); }\n.own-mintlify .ml-btn-secondary:hover { border-color: var(--stone); }\n.own-mintlify .ml-btn-green { background: var(--green); color: var(--primary); }\n.own-mintlify .ml-btn-green:hover { filter: brightness(1.05); }\n.own-mintlify .ml-btn-block { width: 100%; }\n\n/* ── promo + nav ─────────────────────────────────────────────────────────── */\n.own-mintlify .ml-promo { display: flex; align-items: center; justify-content: center; gap: 14px; flex-wrap: wrap; background: var(--canvas-dark); color: #fff; padding: 10px 24px; font-size: 14px; font-weight: 500; }\n.own-mintlify .ml-promo a { color: var(--green); text-decoration: none; font-weight: 600; }\n.own-mintlify .ml-nav { position: sticky; top: 68px; z-index: 30; display: flex; align-items: center; gap: 26px; padding: 12px var(--gut); background: rgba(255,255,255,.92); backdrop-filter: blur(10px); border-bottom: 1px solid var(--hairline-soft); }\n.own-mintlify .ml-logo { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; color: var(--ink); font-weight: 600; font-size: 18px; letter-spacing: -.4px; }\n.own-mintlify .ml-logo-mark { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 8px; background: var(--primary); color: #fff; font-size: 14px; font-weight: 700; }\n.own-mintlify .ml-nav-links { display: flex; align-items: center; gap: 24px; margin-left: 8px; }\n.own-mintlify .ml-nav-links a { color: var(--charcoal-text); text-decoration: none; font-size: 14px; font-weight: 500; }\n.own-mintlify .ml-nav-links a:hover { color: var(--ink); }\n.own-mintlify .ml-nav-right { margin-left: auto; display: flex; align-items: center; gap: 8px; }\n.own-mintlify .ml-menu { display: none; width: 40px; height: 40px; align-items: center; justify-content: center; border: 1px solid var(--hairline); border-radius: 9999px; background: var(--canvas); cursor: pointer; }\n.own-mintlify .ml-menu svg { width: 18px; height: 18px; fill: none; stroke: var(--ink); stroke-width: 2; stroke-linecap: round; }\n\n/* ── hero ────────────────────────────────────────────────────────────────── */\n.own-mintlify .ml-hero { position: relative; overflow: hidden; background: linear-gradient(180deg, var(--sky-from) 0%, #cfd4cf 34%, var(--sky-to) 78%, var(--canvas) 100%); padding: clamp(56px, 9cqi, 120px) var(--gut) 0; }\n.own-mintlify .ml-clouds { position: absolute; inset: 0; pointer-events: none; }\n.own-mintlify .ml-cloud { position: absolute; border-radius: 50%; background: radial-gradient(circle at 40% 40%, rgba(255,255,255,.92), rgba(255,255,255,.4) 60%, transparent 72%); filter: blur(2px); }\n.own-mintlify .ml-cloud-1 { width: 340px; height: 180px; left: 4%; top: 16%; }\n.own-mintlify .ml-cloud-2 { width: 460px; height: 220px; right: 2%; top: 8%; opacity: .75; }\n.own-mintlify .ml-cloud-3 { width: 280px; height: 150px; left: 22%; top: 38%; opacity: .6; }\n.own-mintlify .ml-cloud-4 { width: 380px; height: 190px; right: 16%; top: 40%; opacity: .55; }\n.own-mintlify .ml-hero-inner { position: relative; z-index: 1; max-width: 1000px; margin: 0 auto; text-align: center; }\n.own-mintlify .ml-hero .ml-h1 { max-width: 16ch; margin: 0 auto; }\n.own-mintlify .ml-hero-sub { color: var(--charcoal-text); font-size: 18px; line-height: 1.5; max-width: 54ch; margin: 20px auto 0; }\n.own-mintlify .ml-hero-cta { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-top: 30px; }\n.own-mintlify .ml-mockup { max-width: 860px; margin: clamp(36px, 5cqi, 64px) auto 0; background: var(--canvas); border: 1px solid var(--hairline-soft); border-radius: 12px; overflow: hidden; box-shadow: rgba(0,0,0,.12) 0px 24px 48px -8px; }\n.own-mintlify .ml-mock-top { display: flex; align-items: center; gap: 7px; padding: 12px 16px; border-bottom: 1px solid var(--hairline-soft); }\n.own-mintlify .ml-mock-top span { width: 11px; height: 11px; border-radius: 50%; background: var(--hairline); }\n.own-mintlify .ml-mock-top i { margin-left: 12px; font-family: var(--mono); font-size: 12px; color: var(--stone); font-style: normal; }\n.own-mintlify .ml-mock-body { display: grid; grid-template-columns: 150px 1fr; min-height: 300px; }\n.own-mintlify .ml-mock-side { padding: 18px; border-right: 1px solid var(--hairline-soft); display: grid; align-content: start; gap: 12px; }\n.own-mintlify .ml-mock-side b { display: block; height: 10px; border-radius: 6px; background: var(--surface); }\n.own-mintlify .ml-mock-side b.is-on { background: var(--green-soft); width: 80%; }\n.own-mintlify .ml-mock-side b:nth-child(2) { width: 90%; }\n.own-mintlify .ml-mock-side b:nth-child(3) { width: 64%; }\n.own-mintlify .ml-mock-main { padding: 22px; text-align: left; }\n.own-mintlify .ml-mock-head { height: 18px; width: 40%; border-radius: 6px; background: var(--surface); margin-bottom: 22px; }\n.own-mintlify .ml-mock-chart { display: flex; align-items: flex-end; gap: 12px; height: 160px; }\n.own-mintlify .ml-mock-chart i { flex: 1; height: var(--h); border-radius: 6px 6px 2px 2px; background: linear-gradient(180deg, var(--green-soft), var(--green)); }\n.own-mintlify .ml-mock-lines { display: grid; gap: 10px; margin-top: 22px; }\n.own-mintlify .ml-mock-lines span { height: 12px; border-radius: 6px; background: var(--surface); }\n.own-mintlify .ml-mock-lines span:nth-child(2) { width: 76%; }\n.own-mintlify .ml-mock-lines span:nth-child(3) { width: 54%; }\n\n/* ── logo wall ───────────────────────────────────────────────────────────── */\n.own-mintlify .ml-logos { padding: 40px var(--gut); border-bottom: 1px solid var(--hairline-soft); }\n.own-mintlify .ml-logos-row { display: grid; grid-template-columns: repeat(6, 1fr); gap: 20px; max-width: 1000px; margin: 0 auto; }\n.own-mintlify .ml-logos-row span { text-align: center; font-weight: 500; font-size: 16px; color: var(--steel); }\n\n/* ── sections ───────────────────────────────────────────────────────────── */\n.own-mintlify .ml-sec { padding: clamp(48px, 6cqi, 96px) var(--gut); max-width: 1280px; margin: 0 auto; }\n.own-mintlify .ml-feats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: 40px; }\n.own-mintlify .ml-feat { background: var(--canvas); border: 1px solid var(--hairline); border-radius: 12px; padding: 24px; }\n.own-mintlify .ml-fi { display: grid; place-items: center; width: 42px; height: 42px; border-radius: 10px; background: var(--green-soft); margin-bottom: 18px; }\n.own-mintlify .ml-fi svg { width: 22px; height: 22px; fill: none; stroke: var(--primary); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }\n.own-mintlify .ml-feat-desc { margin-top: 8px; font-size: 14px; line-height: 1.5; color: var(--steel); }\n.own-mintlify .ml-split { display: grid; grid-template-columns: 1fr 1.1fr; gap: clamp(28px, 4cqi, 56px); align-items: center; margin-top: clamp(48px, 6cqi, 80px); }\n.own-mintlify .ml-eyebrow-chip { display: inline-flex; padding: 4px 12px; border-radius: 9999px; background: var(--surface); border: 1px solid var(--hairline); font-size: 12px; font-weight: 600; color: var(--steel); margin-bottom: 16px; }\n.own-mintlify .ml-checks { list-style: none; margin: 24px 0 0; padding: 0; display: grid; gap: 12px; }\n.own-mintlify .ml-checks li { position: relative; padding-left: 30px; font-size: 15px; color: var(--charcoal-text); }\n.own-mintlify .ml-checks li::before { content: ''; position: absolute; left: 0; top: 3px; width: 16px; height: 9px; border-left: 2px solid var(--green-deep); border-bottom: 2px solid var(--green-deep); transform: rotate(-45deg); }\n.own-mintlify .ml-code { border: 1px solid var(--hairline); border-radius: 12px; overflow: hidden; box-shadow: rgba(0,0,0,.08) 0px 4px 12px 0px; }\n.own-mintlify .ml-code-head { display: flex; align-items: center; justify-content: space-between; padding: 10px 16px; background: var(--surface-code); color: #b3b3b3; border-bottom: 1px solid var(--hairline-dark); font-size: 13px; }\n.own-mintlify .ml-copy { background: transparent; border: 1px solid var(--hairline-dark); border-radius: 6px; padding: 3px 8px; color: #b3b3b3; font-family: var(--font); font-size: 12px; cursor: pointer; }\n.own-mintlify .ml-code-body { margin: 0; padding: 20px; background: var(--surface-code); color: #fff; font-family: var(--mono); font-size: 13px; line-height: 1.7; overflow-x: auto; }\n.own-mintlify .ml-code-body .ml-k { color: #7cebcb; }\n.own-mintlify .ml-code-body .ml-s { color: #ffb4a0; }\n\n/* ── stories ─────────────────────────────────────────────────────────────── */\n.own-mintlify .ml-quote-grid { display: grid; grid-template-columns: 1.2fr 1fr; gap: 20px; margin-top: 32px; }\n.own-mintlify .ml-quote-feature { margin: 0; background: var(--orange); color: #fff; border-radius: 12px; padding: clamp(28px, 4cqi, 56px); }\n.own-mintlify .ml-quote-feature blockquote p { font-weight: 600; font-size: clamp(20px, 2.4cqi, 28px); line-height: 1.25; letter-spacing: -.5px; }\n.own-mintlify .ml-quote-feature figcaption { margin-top: 24px; display: grid; gap: 2px; font-size: 14px; }\n.own-mintlify .ml-quote-feature figcaption b { font-weight: 600; }\n.own-mintlify .ml-quote-feature figcaption span { color: rgba(255,255,255,.82); }\n.own-mintlify .ml-quote { margin: 0; background: var(--canvas); border: 1px solid var(--hairline); border-radius: 12px; padding: 32px; display: flex; flex-direction: column; justify-content: center; }\n.own-mintlify .ml-quote blockquote p { font-size: 18px; line-height: 1.4; }\n.own-mintlify .ml-quote figcaption { margin-top: 20px; display: grid; gap: 2px; font-size: 14px; }\n.own-mintlify .ml-quote figcaption b { font-weight: 600; }\n.own-mintlify .ml-quote figcaption span { color: var(--steel); }\n\n/* ── pricing ─────────────────────────────────────────────────────────────── */\n.own-mintlify .ml-price-head { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; }\n.own-mintlify .ml-toggle { display: inline-flex; gap: 4px; padding: 4px; border-radius: 9999px; background: var(--surface); }\n.own-mintlify .ml-toggle-btn { display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 16px; border: 0; border-radius: 9999px; background: transparent; color: var(--steel); font-family: var(--font); font-size: 14px; font-weight: 500; cursor: pointer; }\n.own-mintlify .ml-toggle-btn.is-active { background: var(--canvas); color: var(--ink); box-shadow: rgba(0,0,0,.06) 0px 1px 2px 0px; }\n.own-mintlify .ml-badge-discount { display: inline-flex; padding: 2px 8px; border-radius: 9999px; background: var(--green); color: var(--primary); font-size: 12px; font-weight: 600; }\n.own-mintlify .ml-price-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: 36px; }\n.own-mintlify .ml-price-card { position: relative; background: var(--canvas); border: 1px solid var(--hairline); border-radius: 12px; padding: 32px; display: flex; flex-direction: column; }\n.own-mintlify .ml-price-featured { border: 2px solid var(--green); box-shadow: rgba(0,212,164,.08) 0px 8px 24px; }\n.own-mintlify .ml-badge-featured { position: absolute; top: -12px; left: 32px; padding: 3px 10px; border-radius: 9999px; background: var(--green); color: var(--primary); font-size: 12px; font-weight: 600; }\n.own-mintlify .ml-price { font-weight: 600; font-size: clamp(32px, 4cqi, 46px); letter-spacing: -1.5px; margin: 12px 0 20px; }\n.own-mintlify .ml-price b { font-weight: 600; }\n.own-mintlify .ml-price span { font-size: 14px; font-weight: 400; color: var(--steel); }\n.own-mintlify .ml-price-list { list-style: none; margin: 0 0 26px; padding: 0; display: grid; gap: 12px; flex: 1; }\n.own-mintlify .ml-price-list li { position: relative; padding-left: 28px; font-size: 14px; color: var(--charcoal-text); }\n.own-mintlify .ml-price-list li::before { content: ''; position: absolute; left: 0; top: 4px; width: 15px; height: 8px; border-left: 2px solid var(--green-deep); border-bottom: 2px solid var(--green-deep); transform: rotate(-45deg); }\n.own-mintlify .ml-compare { margin-top: 48px; overflow-x: auto; }\n.own-mintlify .ml-table { width: 100%; border-collapse: collapse; border: 1px solid var(--hairline); border-radius: 8px; overflow: hidden; min-width: 560px; }\n.own-mintlify .ml-table th, .own-mintlify .ml-table td { text-align: left; padding: 14px 18px; font-size: 14px; }\n.own-mintlify .ml-table thead th { background: var(--surface); font-size: 13px; font-weight: 600; color: var(--steel); }\n.own-mintlify .ml-table tbody tr { border-top: 1px solid var(--hairline-soft); }\n.own-mintlify .ml-table-group th { padding: 12px 18px; background: var(--surface-soft); font-size: 11px; font-weight: 600; letter-spacing: .5px; text-transform: uppercase; color: var(--steel); }\n\n/* ── docs ─────────────────────────────────────────────────────────────────── */\n.own-mintlify .ml-docs { max-width: 1280px; }\n.own-mintlify .ml-docs-grid { display: grid; grid-template-columns: 220px minmax(0, 1fr) 190px; gap: 40px; align-items: start; }\n.own-mintlify .ml-side { position: sticky; top: 148px; display: grid; gap: 2px; }\n/* ── badges (docs) ────────────────────────────────────────────────────────── */\n.own-mintlify .ml-side-head { margin: 16px 0 4px; font-size: 11px; font-weight: 600; letter-spacing: .5px; text-transform: uppercase; color: var(--steel); }\n.own-mintlify .ml-side-link { display: block; padding: 7px 12px; border-radius: 6px; font-size: 14px; color: var(--steel); text-decoration: none; }\n.own-mintlify .ml-side-link.is-active { background: var(--surface); color: var(--ink); font-weight: 500; }\n.own-mintlify .ml-side-link:hover { color: var(--ink); }\n.own-mintlify .ml-toc { position: sticky; top: 148px; display: grid; gap: 2px; }\n.own-mintlify .ml-toc-link { display: block; padding: 6px 0; font-size: 14px; color: var(--steel); text-decoration: none; }\n.own-mintlify .ml-toc-link.is-active { color: var(--ink); font-weight: 500; }\n.own-mintlify .ml-docs-body { max-width: 720px; }\n.own-mintlify .ml-property { padding: 16px 0; border-bottom: 1px solid var(--hairline-soft); }\n.own-mintlify .ml-property-head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }\n.own-mintlify .ml-code-inline { padding: 2px 6px; border-radius: 4px; background: var(--surface); border: 1px solid var(--hairline); color: var(--charcoal-text); font-family: var(--mono); font-size: 13px; font-weight: 500; }\n.own-mintlify .ml-badge-type { padding: 2px 6px; border-radius: 6px; background: var(--surface); color: var(--steel); font-family: var(--mono); font-size: 13px; }\n.own-mintlify .ml-badge-required { padding: 2px 6px; border-radius: 6px; background: var(--error); color: #fff; font-size: 11px; font-weight: 600; letter-spacing: .5px; text-transform: uppercase; }\n.own-mintlify .ml-property-desc { margin-top: 8px; font-size: 14px; color: var(--steel); }\n\n/* ── footer ──────────────────────────────────────────────────────────────── */\n.own-mintlify .ml-foot { border-top: 1px solid var(--hairline); padding: clamp(40px, 5cqi, 64px) var(--gut) 32px; }\n.own-mintlify .ml-foot-top { display: grid; grid-template-columns: 220px 1fr; gap: 40px; max-width: 1280px; margin: 0 auto; }\n.own-mintlify .ml-foot-brand { display: flex; align-items: center; gap: 10px; font-weight: 600; font-size: 18px; flex-wrap: wrap; }\n.own-mintlify .ml-foot-brand p { flex-basis: 100%; margin-top: 8px; font-size: 14px; font-weight: 400; color: var(--steel); }\n.own-mintlify .ml-foot-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-mintlify .ml-foot-col h3 { font-size: 14px; font-weight: 600; margin-bottom: 14px; }\n.own-mintlify .ml-foot-col a { display: block; color: var(--steel); text-decoration: none; font-size: 14px; margin-bottom: 10px; }\n.own-mintlify .ml-foot-col a:hover { color: var(--ink); }\n.own-mintlify .ml-foot-bottom { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; max-width: 1280px; margin: 44px auto 0; padding-top: 20px; border-top: 1px solid var(--hairline-soft); font-size: 13px; color: var(--steel); }\n.own-mintlify .ml-foot-links { display: flex; gap: 20px; }\n.own-mintlify .ml-foot-links a { color: var(--steel); text-decoration: none; }\n.own-mintlify .ml-foot-links a:hover { color: var(--ink); }\n\n/* ── responsive ──────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-mintlify .ml-nav-links { display: none; }\n  .own-mintlify .ml-feats { grid-template-columns: 1fr; }\n  .own-mintlify .ml-split { grid-template-columns: 1fr; }\n  .own-mintlify .ml-logos-row { grid-template-columns: repeat(3, 1fr); }\n  .own-mintlify .ml-price-grid { grid-template-columns: 1fr; }\n  .own-mintlify .ml-docs-grid { grid-template-columns: 1fr; gap: 24px; }\n  .own-mintlify .ml-side, .own-mintlify .ml-toc { position: static; }\n  .own-mintlify .ml-toc { display: none; }\n}\n@container frame (max-width: 760px) {\n  .own-mintlify .ml-nav { top: 10px; gap: 12px; padding: 10px 14px; }\n  .own-mintlify .ml-nav-right .ml-btn { display: none; }\n  .own-mintlify .ml-menu { display: inline-flex; margin-left: auto; }\n  .own-mintlify .ml-quote-grid { grid-template-columns: 1fr; }\n  .own-mintlify .ml-foot-top { grid-template-columns: 1fr; gap: 28px; }\n  .own-mintlify .ml-foot-grid { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-mintlify .ml-logos-row { grid-template-columns: repeat(2, 1fr); }\n  .own-mintlify .ml-foot-grid { grid-template-columns: 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-mintlify *, .own-mintlify *::before, .own-mintlify *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Mintlify own-layout behaviour ═════════════════════════════
   Registers window.OWN_LAYOUTS['mintlify'].init(root). Handles the pricing
   monthly/annual toggle, the copy-code button and the mobile menu. Returns a
   cleanup removing every listener and timer. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['mintlify'] = {
    init: function (root) {
      var billBtns = Array.prototype.slice.call(root.querySelectorAll('[data-ml-bill]'));
      var prices = Array.prototype.slice.call(root.querySelectorAll('[data-ml-price]'));
      var copy = root.querySelector('[data-ml-copy]');
      var code = root.querySelector('.ml-code-body');
      var menu = root.querySelector('[data-ml-menu]');
      var links = root.querySelector('.ml-nav-links');
      var timers = [];

      function onBill(e) {
        var mode = e.currentTarget.getAttribute('data-ml-bill');
        billBtns.forEach(function (b) {
          var on = b === e.currentTarget;
          b.classList.toggle('is-active', on);
          b.setAttribute('aria-pressed', on ? 'true' : 'false');
        });
        prices.forEach(function (p) {
          var v = p.getAttribute('data-' + mode);
          if (v) p.textContent = v;
        });
      }
      function onCopy() {
        if (!copy || !code) return;
        try { navigator.clipboard && navigator.clipboard.writeText(code.textContent); } catch (err) { /* ignore */ }
        var prev = copy.textContent;
        copy.textContent = 'Copied';
        timers.push(setTimeout(function () { if (copy) copy.textContent = prev; }, 1400));
      }
      function onMenu() {
        if (!links) return;
        var open = links.getAttribute('data-open') === '1';
        links.setAttribute('data-open', open ? '0' : '1');
        links.style.display = open ? '' : 'grid';
        links.style.position = 'absolute';
        links.style.top = '64px';
        links.style.left = '12px';
        links.style.right = '12px';
        links.style.margin = '0';
        links.style.padding = '14px';
        links.style.gap = '4px';
        links.style.background = '#fff';
        links.style.border = '1px solid var(--hairline)';
        links.style.borderRadius = '12px';
        links.style.boxShadow = 'rgba(0,0,0,.08) 0px 4px 12px 0px';
        links.style.zIndex = '40';
      }

      billBtns.forEach(function (b) { b.addEventListener('click', onBill); });
      if (copy) copy.addEventListener('click', onCopy);
      if (menu) menu.addEventListener('click', onMenu);

      return function cleanup() {
        billBtns.forEach(function (b) { b.removeEventListener('click', onBill); });
        if (copy) copy.removeEventListener('click', onCopy);
        if (menu) menu.removeEventListener('click', onMenu);
        timers.forEach(clearTimeout);
        if (links) { links.removeAttribute('style'); links.removeAttribute('data-open'); }
      };
    }
  };
})();
